	public static Dhikr Random(Dhikr? not = null)
	{
		int num = 0;
		Dhikr dhikr;
		do
		{
			dhikr = All[R.Next(All.Length)];
		}
		while ((object)dhikr == not && ++num < 10);
		return dhikr;
	}

	public static Dhikr RandomShort()
	{
		Dhikr[] array = All.Where((Dhikr x) => x.Text.Length <= 200).ToArray();
		return array[R.Next(array.Length)];
	}
